#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <inttypes.h>

/* Helper to parse a signed 64‑bit integer and detect errors.
   Returns 0 on success, non‑zero on failure. */
static int parse_int64(const char *s, int64_t *out)
{
    char *endptr = NULL;
    errno = 0;
    int64_t v = strtoll(s, &endptr, 10);

    /* No conversion performed */
    if (endptr == s)
        return -1;
    /* Trailing characters */
    if (*endptr != '\0')
        return -1;
    /* Overflow / underflow */
    if (errno == ERANGE)
        return -1;

    *out = v;
    return 0;
}

/* Compute (base^exp) mod mod using binary exponentiation.
   All arguments are non‑negative and mod > 0. */
static int64_t mod_pow(int64_t base, int64_t exp, int64_t mod)
{
    /* Reduce base modulo mod and make it non‑negative */
    base %= mod;
    if (base < 0)
        base += mod;

    int64_t result = 1 % mod;          /* works even when mod == 1 */

    while (exp > 0) {
        if (exp & 1)
            result = (__int128)result * base % mod;
        base = (__int128)base * base % mod;
        exp >>= 1;
    }
    return result;
}

int main(int argc, char **argv)
{
    if (argc < 4) {
        puts("NO_INPUT");
        return 0;
    }

    int64_t base, exp, mod;
    if (parse_int64(argv[1], &base) ||
        parse_int64(argv[2], &exp) ||
        parse_int64(argv[3], &mod)) {
        puts("BAD_INPUT");
        return 0;
    }

    if (mod < 1) {
        puts("BAD_MODULUS");
        return 0;
    }
    if (mod > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (exp < 0) {
        puts("NEGATIVE_EXPONENT");
        return 0;
    }

    int64_t result = mod_pow(base, exp, mod);
    printf("result=%" PRId64 "\n", result);
    return 0;
}
